    {
      "label": "M_PayToProgress",
      "span": "if you want to win anything on this game it will cost hundreds of dollars.",
      "rule_applied": "Pay to Win indicator under M_PayToProgress: patterns that grant advantages or successful advancement to players who spend money.",
      "rationale": "The reviewer states that spending hundreds of dollars is required to win anything in the game."
    },
    {
      "label": "P_CompleteTheCollection",
      "span": "on the stickers you will never get the last one or two unless you pay a lot of money to get them.",
      "rule_applied": "Definition: compulsion to acquire all the items, achievements, or hidden features in a game.",
      "rationale": "The reviewer describes pursuing the final stickers in a set, making completion of the sticker collection the relevant goal."
