    {
      "label": "M_DeceptiveLuxury",
      "span": "you will never get the last one or two unless you pay a lot of money to get them.",
      "rule_applied": "Artificial Scarcity and Rarity Level: scarcity or rarity tied directly to purchase terms or a higher price.",
      "rationale": "The final stickers are presented as effectively unavailable through ordinary play and obtainable only through an expensive purchase, tying manufactured scarcity to price."
    }
  ],
  "invoked_web_search": false,
  "search_query": null,
  "search_result": null
}

